#!/usr/bin/env python3
"""End-to-end test of the v1.3 dashboard against testdata/mock_device_v13.py (http 8081 / ws 81).
   Start the mock first:  python3 testdata/mock_device_v13.py 8081 &
   Checks: Start button and the READY -> calibrating -> measuring -> stopped states, placement and gravity in every
   state (also without a licence), breathing shown from the newest breaths, heart rate paused (not locked) while
   strong breathing shakes the chest, plain-language status, the new alarms, restart and factory reset, themes."""
import asyncio, json, urllib.request, sys, os
from playwright.async_api import async_playwright
CH = "/opt/pw-browsers/chromium-1194/chrome-linux/chrome"
BASE = "http://localhost:8081"
OUT = sys.argv[1] if len(sys.argv) > 1 else "/tmp/ui13"; os.makedirs(OUT, exist_ok=True)
ok = True; npass = 0; nfail = 0
def chk(name, cond, info=""):
    global ok, npass, nfail
    print(("PASS " if cond else "FAIL ") + name, "" if cond else info, flush=True)
    ok = ok and bool(cond)
    if cond: npass += 1
    else: nfail += 1
def get(p): return urllib.request.urlopen(BASE + p).read()
def post(p, data=b""):
    try: return urllib.request.urlopen(urllib.request.Request(BASE + p, data=data, method="POST", headers={"Content-Type": "application/x-www-form-urlencoded"})).read()
    except urllib.error.HTTPError as e: return e.code
def calls(): return json.loads(post("/api/calls"))
def state(): return json.loads(get("/api/state"))
FAKE_AUDIO = """
window.__snd = [];
class FOsc { constructor(){ this.type='sine'; this.frequency = {setValueAtTime:(f)=>{ window.__snd.push(Math.round(f)); }, linearRampToValueAtTime(){} }; } connect(){} start(){} stop(){} }
class FGain { constructor(){ this.gain = {value:1, setValueAtTime(){}, linearRampToValueAtTime(){}}; } connect(){} }
class FCtx { constructor(){ this.state='running'; this.currentTime=0; this.destination={}; } resume(){} createOscillator(){ return new FOsc(); } createGain(){ return new FGain(); } }
window.AudioContext = FCtx; window.webkitAudioContext = FCtx;
"""
async def main():
    get("/api/scn?v=normal"); get("/api/set?k=full&v=1"); get("/api/set?k=sensor&v=1"); get("/api/set?k=tilt&v=0"); get("/api/set?k=mot&v=0")
    if state()["cal"] == 2: post("/api/measure", b"op=stop")
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CH, args=["--no-sandbox"])
        ctx = await b.new_context(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True, device_scale_factor=2)
        await ctx.add_init_script(FAKE_AUDIO)
        await ctx.add_init_script("try{localStorage.setItem('cr_wifi_skip','1')}catch(e){}")
        pg = await ctx.new_page(); errs = []; dialogs = []
        # (503 = the mock answering "restarting" during the restart / factory-reset tests, as a real monitor would not answer then)
        # (403 = the deliberate wrong-PIN test of the alarm limits)
        pg.on("console", lambda m: errs.append(f"{m.type}: {m.text} {m.location.get('url', '')}") if m.type == "error" and "status of 503" not in m.text and not ("status of 403" in m.text and "/api/alarms/login" in m.location.get("url", "")) else None)
        pg.on("pageerror", lambda e: errs.append(f"PAGEERROR: {e.message} {(e.stack or '')[:300]}"))
        pg.on("response", lambda r: errs.append(f"HTTP {r.status} {r.url}") if r.status == 404 else None)
        def on_dialog(d):
            dialogs.append(d.message); asyncio.ensure_future(d.accept())
        pg.on("dialog", on_dialog)
        T = lambda i: pg.text_content("#" + i)
        cls = lambda i: pg.get_attribute("#" + i, "class")
        vis = lambda i: pg.is_visible("#" + i)
        async def wait_js(js, ms=8000):
            try: await pg.wait_for_function(js, timeout=ms); return True
            except Exception: return False
        await pg.goto(BASE + "/#live"); await pg.wait_for_timeout(2500)
        await pg.click("h1.ltitle")                              # one tap unlocks sound like on a phone
        # ---------------- 1. READY: placement and the Start button before measuring ----------------
        chk("ready: hero says Ready to measure", (await T("heroTitle")).startswith("Ready to measure"), await T("heroTitle"))
        chk("ready: hero style s-ready", "s-ready" in (await cls("hero")))
        chk("ready: Start button visible, Stop hidden", await vis("btnStart") and not await vis("btnStop"))
        chk("ready: placement card visible", await vis("orientSec"))
        chk("ready: placement card directly under the hero", await pg.evaluate("document.getElementById('hero').nextElementSibling.id === 'orientSec'"))
        chk("ready: placement drawing shown", await pg.is_visible(".torso svg"))
        chk("ready: gravity source = live preview", "preview" in (await T("oSrc")), await T("oSrc"))
        oc = await T("oChecks")
        chk("ready: posture lying on the back + still", "Lying on the back" in oc and "Still" in oc, oc)
        chk("ready: axis up +Z", (await T("oUp")).startswith("+Z"), await T("oUp"))
        chk("ready: vitals empty", (await T("hrBig")).startswith("--") and (await T("rrBig")).startswith("--"))
        chk("ready: Capture 10 min disabled", await pg.is_disabled("#btnLog"))
        chk("ready: live subtitle", (await T("liveSub")) == "not measuring", await T("liveSub"))
        chk("ready: no calibration banner on the Live page", not await vis("calBanner"))
        await pg.screenshot(path=f"{OUT}/01_ready_phone_light.png", full_page=False)
        get("/api/set?k=tilt&v=80"); await pg.wait_for_timeout(1300)
        oc = await T("oChecks")
        chk("ready: sitting up is recognised from gravity", "Sitting or standing upright" in oc, oc)
        get("/api/set?k=mot&v=1"); await pg.wait_for_timeout(1300)
        chk("ready: movement flagged before Start", "Moving - keep still before Start" in (await T("oChecks")), await T("oChecks"))
        get("/api/set?k=mot&v=0"); get("/api/set?k=tilt&v=0"); await pg.wait_for_timeout(1200)
        # other page: banner tells that nothing is measured
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(1300)
        chk("ready: other pages show a 'Not measuring' banner", await vis("calBanner") and "Not measuring" in (await T("calTitle")), await T("calTitle"))
        await pg.click('.tabs a[data-p="live"]'); await pg.wait_for_timeout(800)
        # ---------------- 2. Start ----------------
        n0 = len(calls())
        await pg.click("#btnStart"); await pg.wait_for_timeout(300)
        c = calls()[n0:]
        chk("start: page sends {cmd:start} once", sum(1 for x in c if x[0] == "ws" and json.loads(x[1]).get("cmd") == "start") == 1, c)
        chk("start: calibrating state shown", await wait_js("document.getElementById('heroTitle').textContent.startsWith('Calibrating')", 4000), await T("heroTitle"))
        chk("start: progress bar and Stop visible", await vis("heroProg") and await vis("btnStop") and not await vis("btnStart"))
        await pg.wait_for_timeout(700)
        await pg.screenshot(path=f"{OUT}/02_calibrating_phone.png")
        chk("measuring: reached", await wait_js("document.getElementById('hero').className.includes('s-ok')", 8000), await cls("hero"))
        await pg.wait_for_timeout(2500)
        chk("measuring: plain-language title", (await T("heroTitle")).startswith("Measuring"), await T("heroTitle"))
        msg = await T("heroMsg")
        chk("measuring: summary names heart and breathing", "Heart" in msg and "Breathing" in msg and "breaths in the last minute" in msg, msg)
        chk("measuring: placement card moved below the assessment", await pg.evaluate("document.getElementById('sevCard').nextElementSibling.id === 'orientSec'"))
        chk("measuring: placement still visible", await vis("orientSec"))
        chk("measuring: gravity source = while measuring", (await T("oSrc")) == "while measuring", await T("oSrc"))
        chk("measuring: breathing big number from the newest breaths", (await T("rrBig")).startswith("16"), await T("rrBig"))
        chk("measuring: 1-min, 5-min and breath count shown", (await T("rrNow")) == "16" and (await T("rr5Top")) in ("15", "16", "17") and (await T("b1mTop")) == "16",
            [await T("rrNow"), await T("rr5Top"), await T("b1mTop")])
        chk("measuring: heart rate shown", (await T("hrBig"))[:2].isdigit(), await T("hrBig"))
        chk("measuring: Capture enabled", not await pg.is_disabled("#btnLog"))
        chk("measuring: long-term observation progress shown", await vis("obsRow") and "of 30 calm minutes" in (await T("obsTxt")), await T("obsTxt"))
        await pg.click("details.clin summary"); await pg.wait_for_timeout(300)
        chk("measuring: NEWS2 meter present", (await T("sevNews")) != "", await T("sevNews"))
        await pg.screenshot(path=f"{OUT}/03_measuring_phone_light.png")
        await pg.screenshot(path=f"{OUT}/03b_measuring_phone_full.png", full_page=True)
        # ---------------- 3. fast breathing shakes the chest ----------------
        get("/api/scn?v=fastbreath"); await pg.wait_for_timeout(2500)
        chk("fast breathing: big breathing number follows at once (46)", (await T("rrBig")).startswith("46"), await T("rrBig"))
        chk("fast breathing: heart card marked as paused", "art" in (await pg.get_attribute("article.vital.heart", "class")))
        chk("fast breathing: explanation note visible", await vis("hrArtNote"))
        chk("fast breathing: no instant heart rate shown", (await T("hrNow")) == "--", await T("hrNow"))
        chk("fast breathing: hero explains breathing (not the heart)", "Breathing" in (await T("heroTitle")), await T("heroTitle"))
        act = await pg.evaluate("CRAlarm.active().map(a => a.k)")
        chk("fast breathing: no heart-rate alarm", "heart" not in act, act)
        await pg.screenshot(path=f"{OUT}/04_fast_breathing_phone.png")
        # ---------------- 4. no signal from the body ----------------
        r = await pg.evaluate("""() => { const P = ageProfile(70);
            const S = {cal:2, win:120, mot:0, pres:0, hr:null, rr:null, rr1:null, rrn:null, sqh:3, sqr:4, apc:0};
            const c1 = CRAlarm.conditions(S, {P, full:1, v:null});
            const c2 = CRAlarm.conditions(Object.assign({}, S, {mot:1}), {P, full:1, v:null});
            const c3 = CRAlarm.conditions(Object.assign({}, S, {win:20}), {P, full:1, v:null});
            return [!!c1.nosig, !!c2.nosig, !!c3.nosig, c1.nosig && c1.nosig.hold]; }""")
        chk("no-signal alarm: only while still, after 45 s of measuring, 30 s hold", r == [True, False, False, 30000], r)
        get("/api/scn?v=nosig"); get("/api/set?k=meas_t0&v=-400"); await pg.wait_for_timeout(2000)
        chk("no signal: hero asks to check the sensor", "No clear signal" in (await T("heroTitle")), await T("heroTitle"))
        # ---------------- 5. breathing pause -> urgent alarm ----------------
        get("/api/scn?v=apnea"); await pg.wait_for_timeout(1500)
        await pg.evaluate("window.__snd = []")
        chk("apnoea: warning after the age limit (10 s)", await wait_js("CRAlarm.active().some(a => a.k === 'apnea')", 14000))
        chk("apnoea: urgent and hero red after 20 s", await wait_js("document.getElementById('hero').className.includes('s-alert')", 14000), await cls("hero"))
        chk("apnoea: hero title names the pause", "Breathing pause" in (await T("heroTitle")), await T("heroTitle"))
        chk("apnoea: alarm bar visible", await vis("alarmBar"))
        await pg.wait_for_timeout(600)
        snd = await pg.evaluate("window.__snd")
        chk("apnoea: siren sound played", 880 in snd and 587 in snd, snd[:12])
        await pg.screenshot(path=f"{OUT}/05_apnoea_alarm_phone.png")
        get("/api/scn?v=normal"); await pg.wait_for_timeout(5000)
        chk("apnoea over: hero back to normal", "s-ok" in (await cls("hero")) or "s-watch" in (await cls("hero")), [await cls("hero"), await T("heroTitle")])
        # ---------------- 6. Stop from this page (confirm) ----------------
        n0 = len(calls()); dialogs.clear()
        await pg.click("#btnStop"); await pg.wait_for_timeout(600)
        c = calls()[n0:]
        chk("stop: confirmation asked", len(dialogs) == 1 and "Stop the measurement" in dialogs[0], dialogs)
        chk("stop: page sends {cmd:stop}", any(x[0] == "ws" and json.loads(x[1]).get("cmd") == "stop" for x in c), c)
        chk("stop: back to Ready", await wait_js("document.getElementById('heroTitle').textContent.startsWith('Ready')", 4000), await T("heroTitle"))
        chk("stop: placement back on top", await pg.evaluate("document.getElementById('hero').nextElementSibling.id === 'orientSec'"))
        chk("stop: vitals cleared", (await T("rrBig")).startswith("--"))
        await pg.wait_for_timeout(4500)
        await pg.evaluate("CRAlarm.state.userStopAt -= 60000")          # as if the deliberate stop was a minute ago
        await pg.wait_for_timeout(4500)
        act = await pg.evaluate("CRAlarm.active().map(a => a.k)")
        chk("stop from this page: no 'measurement stopped' alarm, also a minute later", "stopped" not in act, act)
        # ---------------- 7. stopped elsewhere (button on the monitor / another phone) ----------------
        post("/api/measure", b"op=start")
        chk("measuring again (started elsewhere)", await wait_js("document.getElementById('heroTitle').textContent.startsWith('Measuring')", 9000), await T("heroTitle"))
        post("/api/measure", b"op=stop")
        chk("stopped elsewhere: 'Measurement stopped' notice", await wait_js("CRAlarm.active().some(a => a.k === 'stopped')", 8000), await pg.evaluate("CRAlarm.active()"))
        await pg.click("#btnStart")
        chk("start again clears the notice", await wait_js("!CRAlarm.active().some(a => a.k === 'stopped')", 9000))
        await wait_js("document.getElementById('heroTitle').textContent.startsWith('Measuring')", 9000)
        # ---------------- 8. basic mode (no licence): placement and gravity still shown ----------------
        get("/api/set?k=full&v=0"); await pg.wait_for_timeout(2500)
        chk("lite: body.lite set", "lite" in (await pg.get_attribute("body", "class") or ""))
        chk("lite: placement card visible without licence", await vis("orientSec") and await pg.is_visible("#cvLevel"))
        chk("lite: orientation values filled", (await T("oUp")).startswith("+Z") and "Still" in (await T("oChecks")), [await T("oUp"), await T("oChecks")])
        chk("lite: breathing and heart values", (await T("rrBig")).startswith("16") and (await T("hrBig"))[:2].isdigit(), [await T("rrBig"), await T("hrBig")])
        chk("lite: assessment explains basic mode", "Basic mode" in (await T("sevCond")), await T("sevCond"))
        chk("lite: hero still plain language", (await T("heroTitle")).startswith("Measuring"), await T("heroTitle"))
        await pg.screenshot(path=f"{OUT}/06_lite_measuring_phone.png", full_page=True)
        post("/api/measure", b"op=stop"); await pg.wait_for_timeout(1500)
        chk("lite + not measuring: placement and Start shown", await vis("orientSec") and await vis("btnStart"))
        await pg.screenshot(path=f"{OUT}/07_lite_ready_phone.png")
        get("/api/set?k=full&v=1"); await pg.wait_for_timeout(1200)
        # ---------------- 9. sensor missing ----------------
        get("/api/set?k=sensor&v=0"); await pg.wait_for_timeout(1500)
        chk("no sensor: red hero", "s-alert" in (await cls("hero")) and "Sensor" in (await T("heroTitle")), await T("heroTitle"))
        chk("no sensor: Start hidden", not await vis("btnStart"))
        chk("no sensor: placement says not connected", "not connected" in (await T("oChecks")) or "Waiting" in (await T("oChecks")), await T("oChecks"))
        await pg.screenshot(path=f"{OUT}/08_no_sensor_phone.png")
        get("/api/set?k=sensor&v=1"); await pg.wait_for_timeout(1500)
        chk("sensor back: Ready again", (await T("heroTitle")).startswith("Ready"), await T("heroTitle"))
        # ---------------- 10. restart and factory reset ----------------
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(800)
        await pg.locator("#rstCard").scroll_into_view_if_needed()
        await pg.screenshot(path=f"{OUT}/09_settings_reset_phone.png")
        n0 = len(calls()); dialogs.clear()
        await pg.click("#btnReboot"); await pg.wait_for_timeout(800)
        c = calls()[n0:]
        chk("restart: confirmed and sent", len(dialogs) == 1 and any(x[0] == "/api/reboot" for x in c), [dialogs, c])
        chk("restart: message", "restarting" in (await T("rbMsg")).lower(), await T("rbMsg"))
        await pg.click('.tabs a[data-p="live"]')
        chk("restart: page reconnects by itself (fresh uptime)", await wait_js("CR.st.S && CR.st.S.up < 15000 && document.getElementById('heroTitle').textContent.startsWith('Ready')", 25000), [await T("heroTitle"), await pg.evaluate("CR.st.S && CR.st.S.up")])
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(500)
        n0 = len(calls()); dialogs.clear()
        await pg.check("#facLic")
        await pg.click("#btnFactory"); await pg.wait_for_timeout(1000)
        c = calls()[n0:]
        fac = [x for x in c if x[0] == "/api/factory"]
        chk("factory: two confirmations when the licence is removed too", len(dialogs) == 2, dialogs)
        chk("factory: lic=remove sent", len(fac) == 1 and fac[0][1].get("lic") == "remove", c)
        chk("factory: message says licence removed", "licence removed" in (await T("facMsg")), await T("facMsg"))
        await pg.uncheck("#facLic")
        await pg.click('.tabs a[data-p="live"]')
        chk("factory: back in basic mode after the restart", await wait_js("document.body.classList.contains('lite') && document.getElementById('heroTitle').textContent.startsWith('Ready')", 20000))
        get("/api/set?k=full&v=1"); get("/api/set?k=lic_tok&v=1"); await pg.wait_for_timeout(1500)
        n0 = len(calls()); dialogs.clear()
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(400)
        await pg.click("#btnFactory"); await pg.wait_for_timeout(800)
        fac = [x for x in calls()[n0:] if x[0] == "/api/factory"]
        chk("factory (keep licence): one confirmation, no lic parameter", len(dialogs) == 1 and len(fac) == 1 and "lic" not in fac[0][1], [dialogs, fac])
        await pg.click('.tabs a[data-p="live"]')
        await pg.wait_for_timeout(3000)
        chk("factory (keep licence): page back after the restart", await wait_js("CR.st.S && CR.st.S.up < 15000 && document.getElementById('heroTitle').textContent.startsWith('Ready')", 25000))
        chk("factory (keep licence): full mode kept", not await pg.evaluate("document.body.classList.contains('lite')"))
        # ---------------- 11. HTTP API ----------------
        chk("api: start without sensor refused (409)", (get("/api/set?k=sensor&v=0"), post("/api/measure", b"op=start"))[1] == 409)
        get("/api/set?k=sensor&v=1"); await pg.wait_for_timeout(800)
        chk("api: bad op refused (400)", post("/api/measure", b"op=x") == 400)
        # ---------------- 11b. simple local names, QR codes, own network kept on, other monitors ----------------
        chk("names: header shows the simple name", (await T("netChip")) == "cardio2.local", await T("netChip"))
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(300)
        await pg.evaluate("CR.refreshNet()"); await pg.wait_for_timeout(1200)
        chk("names: simple address shown big", (await T("netAddr")) == "http://cardio2.local", await T("netAddr"))
        chk("names: IP shown for phones without .local", "192.168.1.57" in (await T("netAddr2")), await T("netAddr2"))
        ni = await T("netInfo")
        chk("names: old unique name still listed", "cardio-a1b2c3.local" in ni and "automatic" in ni, ni)
        chk("names: QR codes drawn", await pg.locator("#qrOpen svg path").count() == 1 and await pg.locator("#qrJoin svg path").count() == 1)
        await pg.locator("#netShare").scroll_into_view_if_needed()
        import cv2, numpy as np
        dec = []
        for qid in ("qrOpen", "qrJoin"):
            png = await pg.locator("#" + qid).screenshot()
            img = cv2.imdecode(np.frombuffer(png, np.uint8), cv2.IMREAD_GRAYSCALE)
            img = cv2.copyMakeBorder(img, 40, 40, 40, 40, cv2.BORDER_CONSTANT, value=255)
            txt, _, _ = cv2.QRCodeDetector().detectAndDecode(img)
            dec.append(txt)
        chk("names: 'open' QR decodes to the monitor's address", dec[0] == "http://192.168.1.57/", dec[0])
        chk("names: 'join' QR decodes to the own Wi-Fi with its password", dec[1] == "WIFI:T:WPA;S:CardioResp-A1B2C3;P:Xy7pQ2mN9k;;", dec[1])
        await pg.screenshot(path=f"{OUT}/09b_settings_network_phone.png")
        chk("own network: switch shown and on", await vis("netApKeepRow") and await pg.is_checked("#netApKeep"))
        n0 = len(calls())
        await pg.uncheck("#netApKeep"); await pg.wait_for_timeout(600)
        c = [x for x in calls()[n0:] if x[0] == "/api/wifi/apkeep"]
        chk("own network: switching off sends on=0", len(c) == 1 and c[0][1].get("on") == "0", c)
        await pg.check("#netApKeep"); await pg.wait_for_timeout(600)
        chk("own network: switched on again", state() and json.loads(get("/api/wifi"))["apKeep"] == 1)
        await pg.click("#netChange"); await pg.wait_for_timeout(400)
        chk("names: set-up form leaves the name empty (= automatic)", (await pg.input_value("#wHost")) == "" and "cardio2" in (await pg.get_attribute("#wHost", "placeholder")))
        await pg.click("#wCancel")
        await pg.click('.tabs a[data-p="mesh"]')
        chk("other monitors: listed with simple names", await wait_js("document.getElementById('peerList').textContent.includes('cardio3.local')", 8000), await T("peerList"))
        pl = await T("peerList")
        chk("other monitors: this one, a labelled one and its IP", "cardio2.local" in pl and "cardio.local" in pl and "Bed 2" in pl and "192.168.1.40" in pl, pl)
        chk("other monitors: links open their dashboards", await pg.get_attribute('#peerList a[href="http://cardio3.local/"]', "target") == "_blank")
        await pg.locator("#peerCard").scroll_into_view_if_needed()
        await pg.screenshot(path=f"{OUT}/09c_monitors_on_wifi_phone.png")
        # ---------------- 11c. alarm limits (set points, time windows), doctor / nurse PIN ----------------
        get("/api/almreset")
        await pg.click('.tabs a[data-p="settings"]'); await pg.wait_for_timeout(800)
        await pg.locator("#almCard").scroll_into_view_if_needed()
        chk("limits: age-based defaults shown to everybody", "Age-based defaults" in (await T("almSrc")), await T("almSrc"))
        av = await T("almView")
        chk("limits: default set points visible (HR 50/120, RR 10/24, pause 10 s)", all(x in av for x in ("Alarm above120", "Alarm below50", "Alarm above24", "Alarm after (s)10")), av[:300])
        chk("limits: factory-PIN warning shown", await vis("almPinWarn"))
        chk("limits: values cannot be edited without the PIN", await pg.locator("#almView input").count() == 0)
        await pg.click("#almEdit"); await pg.wait_for_timeout(300)
        chk("limits: PIN asked first", await vis("almLogin") and not await vis("almForm"))
        await pg.fill("#almPin", "1111"); await pg.click("#almUnlock"); await pg.wait_for_timeout(700)
        chk("limits: wrong PIN refused", "Wrong PIN" in (await T("almMsg")) and not await vis("almForm"), await T("almMsg"))
        await pg.screenshot(path=f"{OUT}/18_limits_pin_phone.png")
        await pg.fill("#almPin", "1234"); await pg.click("#almUnlock"); await pg.wait_for_timeout(800)
        chk("limits: correct PIN unlocks the form", await vis("almForm") and await pg.locator("#almView input").count() == 17)
        chk("limits: age defaults ticked, fields locked", await pg.is_checked("#almAuto") and await pg.is_disabled("#al_hrHi"))
        await pg.uncheck("#almAuto"); await pg.wait_for_timeout(200)
        chk("limits: fields editable after un-ticking", not await pg.is_disabled("#al_hrHi"))
        await pg.fill("#almBy", "")
        await pg.fill("#al_hrHi", "60"); await pg.fill("#al_hrLo", "40"); await pg.fill("#al_hrLoU", "30"); await pg.fill("#al_hrDly", "2")
        await pg.click("#almSave"); await pg.wait_for_timeout(300)
        chk("limits: name required", "Enter your name" in (await T("almMsg")), await T("almMsg"))
